/**
 * app.c
 * Main application logic. Nothing in here blocks for long:
 *  - UART bytes arrive by interrupt into a ring buffer
 *  - the main loop assembles lines, runs commands, streams data,
 *    and blinks the heartbeat LED using HAL_GetTick() (no HAL_Delay)
 */
#include "app.h"
#include "main.h"
#include "usart.h" /* huart1 generated by CubeMX */
#include "ring_buffer.h"
#include "protocol.h"
#include "mpu6050.h"

#include <stdio.h>
#include <string.h>

#define HEARTBEAT_PERIOD_MS 500u
/* 1 = interrupt-driven RX (real hardware)
 * 0 = polling fallback (for simulators without USART RX interrupt support) */
#define UART_RX_USE_INTERRUPT 0
static ring_buffer_t s_rx_rb;
static uint8_t       s_rx_byte;            /* 1-byte buffer the HAL fills on each RX interrupt */
static volatile uint32_t s_uart_errors = 0u;

static char     s_line[CMD_MAX_LEN + 1u];  /* command line being assembled */
static uint16_t s_line_len = 0u;
static bool     s_line_too_long = false;
static bool     s_line_corrupt  = false;   /* bytes were lost (ring buffer overflow) */
static uint32_t s_seen_overflows = 0u;
static bool     s_prev_was_cr = false;     /* for \r\n handling */
static app_config_t s_cfg = { .stream_on = false, .stream_period_ms = RATE_DEFAULT_MS };
static uint32_t s_last_stream_ms    = 0u;
static uint32_t s_stream_seq        = 0u;
static uint32_t s_last_heartbeat_ms = 0u;

/* ------------------------------------------------------------------ */
/* UART helpers                                                        */
/* ------------------------------------------------------------------ */
static void uart_send_line(const char *s)
{
    HAL_UART_Transmit(&huart1, (uint8_t *)s, (uint16_t)strlen(s), 100u);
    HAL_UART_Transmit(&huart1, (uint8_t *)"\r\n", 2u, 100u);
}

static void uart_start_rx(void)
{
    /* Ask HAL to receive 1 byte by interrupt. When it arrives,
     * HAL_UART_RxCpltCallback() is called and we re-arm. */
    HAL_UART_Receive_IT(&huart1, &s_rx_byte, 1u);
}

/* Called by HAL from the USART1 interrupt (ISR context: keep it short!) */
void HAL_UART_RxCpltCallback(UART_HandleTypeDef *huart)
{
    if (huart->Instance == USART1)
    {
        (void)rb_push(&s_rx_rb, s_rx_byte);
        uart_start_rx();
    }
}

/* Called by HAL on overrun / framing / noise errors: count and re-arm RX */
void HAL_UART_ErrorCallback(UART_HandleTypeDef *huart)
{
    if (huart->Instance == USART1)
    {
        s_uart_errors++;
        uart_start_rx();
    }
}

uint32_t app_rx_overflow_count(void) { return s_rx_rb.overflow_count; }
uint32_t app_uart_error_count(void)  { return s_uart_errors; }

/* ------------------------------------------------------------------ */
/* Main-loop tasks                                                     */
/* ------------------------------------------------------------------ */
static void handle_complete_line(void)
{
    char reply[REPLY_MAX_LEN];

    if (s_line_corrupt)
    {
        /* Some bytes of this line were dropped - never execute a damaged command */
        snprintf(reply, sizeof(reply), "ERR,RX_OVERFLOW");
        uart_send_line(reply);
    }
    else if (s_line_too_long)
    {
        snprintf(reply, sizeof(reply), "ERR,TOO_LONG");
        uart_send_line(reply);
    }
    else if (s_line_len > 0u) /* empty lines are ignored */
    {
        s_line[s_line_len] = '\0';
        protocol_handle_line(s_line, reply, sizeof(reply), &s_cfg);
        uart_send_line(reply);
    }

    s_line_len = 0u;
    s_line_too_long = false;
    s_line_corrupt = false;
}
static void poll_uart_rx(void)
{
#if !UART_RX_USE_INTERRUPT
    /* RXNE = "a byte is waiting". Reading DR clears the flag. */
    while (__HAL_UART_GET_FLAG(&huart1, UART_FLAG_RXNE))
    {
        uint8_t b = (uint8_t)(huart1.Instance->DR & 0xFFu);
        (void)rb_push(&s_rx_rb, b);
    }
    /* Overrun: a byte arrived before we read the previous one */
    if (__HAL_UART_GET_FLAG(&huart1, UART_FLAG_ORE))
    {
        __HAL_UART_CLEAR_OREFLAG(&huart1);
        s_uart_errors++;
    }
#endif
}
static void process_rx(void)
{
    uint8_t b;

    while (rb_pop(&s_rx_rb, &b))
    {
        if (s_rx_rb.overflow_count != s_seen_overflows)
        {
            s_seen_overflows = s_rx_rb.overflow_count;
            s_line_corrupt = true;
        }
        /* A line ends with \r, \n or \r\n (terminals often send only \r on Enter).
         * The \n of a \r\n pair is skipped so it does not count as a second line. */
        if (b == '\r')
        {
            handle_complete_line();
            s_prev_was_cr = true;
            continue;
        }
        if (b == '\n')
        {
            if (!s_prev_was_cr)
            {
                handle_complete_line();
            }
            s_prev_was_cr = false;
            continue;
        }
        s_prev_was_cr = false;
        if (s_line_len < CMD_MAX_LEN)
        {
            s_line[s_line_len++] = (char)b;
        }
        else
        {
            s_line_too_long = true; /* keep discarding until the newline */
        }
    }
}
static void process_stream(void)
{
    char msg[REPLY_MAX_LEN];
    int32_t t;
    uint32_t now;
    sensor_status_t st;

    if (!s_cfg.stream_on) { return; }

    now = HAL_GetTick();
    if ((now - s_last_stream_ms) < s_cfg.stream_period_ms) { return; } /* wrap-safe */
    s_last_stream_ms = now;

    st = mpu6050_read_temp_centi(&t);
    if (st == SENSOR_OK)
    {
        snprintf(msg, sizeof(msg), "DATA,%lu,TEMP,%ld", (unsigned long)s_stream_seq, (long)t);
    }
    else
    {
        snprintf(msg, sizeof(msg), "DATA,%lu,ERR,%s", (unsigned long)s_stream_seq, sensor_status_str(st));
    }
    s_stream_seq++;
    uart_send_line(msg);
}

static void process_heartbeat(void)
{
    uint32_t now = HAL_GetTick();
    if ((now - s_last_heartbeat_ms) >= HEARTBEAT_PERIOD_MS)
    {
        s_last_heartbeat_ms = now;
        HAL_GPIO_TogglePin(GPIOC, GPIO_PIN_13);
    }
}

/* ------------------------------------------------------------------ */
/* Public API                                                          */
/* ------------------------------------------------------------------ */
void app_init(void)
{
    char msg[REPLY_MAX_LEN];
    sensor_status_t st;

    rb_init(&s_rx_rb);

    st = mpu6050_init();
    snprintf(msg, sizeof(msg), "BOOT,%s,%s,SENSOR=%s", FW_NAME, FW_VERSION, sensor_status_str(st));
    uart_send_line(msg);

#if UART_RX_USE_INTERRUPT
    uart_start_rx();
#endif
}

void app_loop(void)
{
    poll_uart_rx();
    process_rx();
    process_stream();
    process_heartbeat();
}
